package ee.schimke.ha.rc.components

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * The fonts a card names ([HaDigital7Font]) that ship with the app rather than the device, as bytes
 * every player we host can load: the AndroidX View player through a typeface resolver, and the
 * Compose players (Android, desktop, browser) through their typeface loader.
 *
 * Digital-7 Mono Italic, Copyright Sizenko Alexander, Style-7: free for non-commercial use, bundled
 * for the Rugged Digital card style; Russo One, Copyright Jovanny Lemonad, SIL Open Font License
 * 1.1, its headings (see THIRD_PARTY_NOTICES.md).
 */
object HaBundledFonts {
  /** Digital-7 Mono Italic's TrueType bytes. */
  @OptIn(ExperimentalEncodingApi::class)
  val digital7: ByteArray by lazy { Base64.decode(Digital7Base64) }

  /**
   * Russo One's TrueType bytes, in two literals: one would pass the JVM's 64 KiB constant limit.
   */
  @OptIn(ExperimentalEncodingApi::class)
  val russoOne: ByteArray by lazy { Base64.decode(RussoOneBase64A + RussoOneBase64B) }

  /** The bundled font named [name], or null when the app doesn't ship one. */
  fun bytes(name: String): ByteArray? =
    when (name) {
      HaDigital7Font -> digital7
      HaGSpotFont -> russoOne
      else -> null
    }
}

